original_text:
{
      "edge": "D03-SRC-001",
      "expected": "DENY denial_reason=duplicate_conflict; no original broker_operation transition NOT_SENT→ATTEMPTED at version 7; state/version/claim/reservation unchanged by denied request; zero COMMITTED; zero broker calls. No precommit receipt, duplicate intent, or a second send-claim under an intent that already holds one => deny; no blind resend",
      "id": "SD1-EDGE-001-NEG",
      "input": {
        "baseline": {
          "aggregate_id": "AGG-SYN-001",
          "axis": "broker_operation",
          "broker_wire_calls_allowed": 0,
          "exact_guard_predicate": "Durable attempt identity, canonical intent, same-account bound entitlement, already-committed gross claim, positive safety checks at future G3; no other send with same key; at most one wire attempt per intent: a send-claim under an intent that already holds a committed send-claim is denied, whatever the attempt id or key; committed as one expected-version CAS together with attempt send-eligibility ELIGIBLE_NO_WIRE→WIRE_ATTEMPTED and intent INTENT_ACTIVE→INTENT_BROKER_OUTCOME_UNRESOLVED (master V1.8 §3.3 rows); permit and correlation key journaled before any network call",
          "expected_version": 7,
          "fixture_type": "LOCAL_ONLY_SYNTHETIC",
          "from_state": "NOT_SENT",
          "requested_to_state": "ATTEMPTED",
          "valid_source_evidence": {
            "account_scope_hash": "sha256:SYNTHETIC-SCOPE",
            "evidence_fields": {
              "account_scope_matches": true,
              "attempt_eligibility": "ELIGIBLE_NO_WIRE",
              "durable_send_claim": true,
              "gross_reservation_held": "100.00 GBP",
              "intent_state": "INTENT_ACTIVE",
              "journal_before_wire": true,
              "other_send_claims_under_intent": 0
            },
            "source_event_ref": "SRC-SYN-001",
            "timestamp_utc": "2026-01-01T12:00:00Z"
          }
        },
        "requested_pair": {
          "axis": "broker_operation",
          "from": "NOT_SENT",
          "to": "ATTEMPTED"
        },
        "single_mutation": {
          "field": "valid_source_evidence.evidence_fields.other_send_claims_under_intent",
          "from": 0,
          "to": 1
        }
      },
      "kind": "SYNTHETIC_DENIAL"
    }

