{
      "edge": "D03-SRC-005",
      "expected": "DENY denial_reason=evidence_incomplete; no original broker_operation transition UNKNOWN→REJECTED at version 7; state/version/claim/reservation unchanged by denied request; zero COMMITTED; zero broker calls. Rejection alone with possible partial execution cannot justify exposure release",
      "id": "SD1-EDGE-005-NEG",
      "input": {
        "baseline": {
          "aggregate_id": "AGG-SYN-005",
          "axis": "broker_operation",
          "broker_wire_calls_allowed": 0,
          "exact_guard_predicate": "Authoritative negative broker evidence plus independently reconciled proof of no executed/partial fill for this attempt; a duplicate-order or conflicting-order response is not authoritative negative evidence on its own (master V1.8 §3.3 D03 reason-code invariant)",
          "expected_version": 7,
          "fixture_type": "LOCAL_ONLY_SYNTHETIC",
          "from_state": "UNKNOWN",
          "requested_to_state": "REJECTED",
          "valid_source_evidence": {
            "account_scope_hash": "sha256:SYNTHETIC-SCOPE",
            "evidence_fields": {
              "all_possibly_sent_attempts_reconciled": true,
              "broker_rejection_code": "AUTHORITATIVE_NO_EXECUTION",
              "duplicate_or_conflicting_order_code": false,
              "partial_fill_present": false,
              "prior_operation": "UNKNOWN"
            },
            "source_event_ref": "SRC-SYN-005",
            "timestamp_utc": "2026-01-01T12:00:00Z"
          }
        },
        "requested_pair": {
          "axis": "broker_operation",
          "from": "UNKNOWN",
          "to": "REJECTED"
        },
        "single_mutation": {
          "field": "valid_source_evidence.evidence_fields.all_possibly_sent_attempts_reconciled",
          "from": true,
          "to": false
        }
      },
      "kind": "SYNTHETIC_DENIAL"
